using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns detailed statistics about a message. Can be used only if messageProperties.can_get_statistics == true
    /// </summary>
    public Task<TdLib.TdApi.Objects.MessageStatistics> GetMessageStatisticsAsync(long chatId = default, long messageId = default, bool isDark = default)
    {

           using var activity =  StartCallActivity("GetMessageStatisticsAsync", typeof(GetMessageStatistics).FullName ?? "GetMessageStatisticsAsync");

           try
           {
             return client.GetMessageStatisticsAsync(chatId, messageId, isDark);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
